import { test, expect } from '@playwright/test';

test.describe('Account Deletion - Password Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/account/settings');
  });

  test('should successfully delete account after confirming password', async ({ page }) => {
    // Verify account settings page is visible
    const settingsHeader = page.getByRole('heading', { name: /account settings/i });
    await expect(settingsHeader).toBeVisible();

    // Click delete account button
    const deleteButton = page.getByRole('button', { name: /delete account/i });
    await deleteButton.click();

    // Verify confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm account deletion/i });
    await expect(confirmModal).toBeVisible();

    // Enter password in password input field
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('ValidPassword123');

    // Click confirm delete button
    const confirmDeleteButton = page.getByRole('button', { name: /confirm deletion/i });
    await confirmDeleteButton.click();

    // Verify success message
    const successMessage = page.getByText(/account deleted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to login page
    await expect(page).toHaveURL(/.*login/);
  });

  test('should prevent account deletion when password does not match', async ({ page }) => {
    // Verify account settings page is visible
    const settingsHeader = page.getByRole('heading', { name: /account settings/i });
    await expect(settingsHeader).toBeVisible();

    // Click delete account button
    const deleteButton = page.getByRole('button', { name: /delete account/i });
    await deleteButton.click();

    // Verify confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm account deletion/i });
    await expect(confirmModal).toBeVisible();

    // Enter incorrect password
    const passwordInput = page.getByLabel(/password/i);
    await passwordInput.fill('WrongPassword123');

    // Click confirm delete button
    const confirmDeleteButton = page.getByRole('button', { name: /confirm deletion/i });
    await confirmDeleteButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/incorrect password/i);
    await expect(errorMessage).toBeVisible();

    // Verify user remains on settings page
    await expect(settingsHeader).toBeVisible();
    await expect(page).toHaveURL(/.*account\/settings/);
  });
});
